package net.civeira.phylax.feature.observe.observedalert.domain;

import java.time.LocalDateTime;
import java.time.ZoneId;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.feature.observe.observedalertrule.domain.ObservedAlertRuleReference;

class ObservedAlertChangeSetUnitTest {

  /**
   * @autogenerated CachedGenerator
   */
  @Test
  @DisplayName("Test a entity reference contruction")
  void test_observed_alert_change_set_builder() {
    ObservedAlertChangeSet one =
        new ObservedAlertChangeSet().uid("one").rule(ObservedAlertRuleReference.of("one"))
            .problemKey("one").status(ObservedAlertStatusOptions.FIRING).summary("one").link("one")
            .firedAt(LocalDateTime.of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid"))
                .toOffsetDateTime())
            .resolvedAt(LocalDateTime.of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid"))
                .toOffsetDateTime())
            .lastNotifiedAt(LocalDateTime.of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid"))
                .toOffsetDateTime())
            .version(1).newUid();
    one.uid("two");
    Assertions.assertEquals("two", one.getUid().get(), "Value must equals to the assigned value");
    one.unset("uid");
    Assertions.assertFalse(one.getUid().isPresent(), "After unset, the valeue must be dissapear");
    Assertions.assertEquals(ObservedAlertRuleReference.of("one"), one.getRule().get(),
        "Value must equals to the intial value");
    one.rule(ObservedAlertRuleReference.of("two"));
    Assertions.assertEquals(ObservedAlertRuleReference.of("two"), one.getRule().get(),
        "Value must equals to the assigned value");
    one.unset("rule");
    Assertions.assertFalse(one.getRule().isPresent(), "After unset, the valeue must be dissapear");
    Assertions.assertEquals("one", one.getProblemKey().get(),
        "Value must equals to the intial value");
    one.problemKey("two");
    Assertions.assertEquals("two", one.getProblemKey().get(),
        "Value must equals to the assigned value");
    one.unset("problemKey");
    Assertions.assertFalse(one.getProblemKey().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(ObservedAlertStatusOptions.FIRING, one.getStatus().get(),
        "Value must equals to the intial value");
    one.status(ObservedAlertStatusOptions.RESOLVED);
    Assertions.assertEquals(ObservedAlertStatusOptions.RESOLVED, one.getStatus().get(),
        "Value must equals to the assigned value");
    one.unset("status");
    Assertions.assertFalse(one.getStatus().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals("one", one.getSummary().get(), "Value must equals to the intial value");
    one.summary("two");
    Assertions.assertEquals("two", one.getSummary().get(),
        "Value must equals to the assigned value");
    one.unset("summary");
    Assertions.assertFalse(one.getSummary().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals("one", one.getLink().get(), "Value must equals to the intial value");
    one.link("two");
    Assertions.assertEquals("two", one.getLink().get(), "Value must equals to the assigned value");
    one.unset("link");
    Assertions.assertFalse(one.getLink().isPresent(), "After unset, the valeue must be dissapear");
    Assertions.assertEquals(
        LocalDateTime.of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime(),
        one.getFiredAt().get(), "Value must equals to the intial value");
    one.firedAt(
        LocalDateTime.of(1981, 9, 6, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime());
    Assertions.assertEquals(
        LocalDateTime.of(1981, 9, 6, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime(),
        one.getFiredAt().get(), "Value must equals to the assigned value");
    one.unset("firedAt");
    Assertions.assertFalse(one.getFiredAt().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(
        LocalDateTime.of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime(),
        one.getResolvedAt().get(), "Value must equals to the intial value");
    one.resolvedAt(
        LocalDateTime.of(1981, 9, 6, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime());
    Assertions.assertEquals(
        LocalDateTime.of(1981, 9, 6, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime(),
        one.getResolvedAt().get(), "Value must equals to the assigned value");
    one.unset("resolvedAt");
    Assertions.assertFalse(one.getResolvedAt().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(
        LocalDateTime.of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime(),
        one.getLastNotifiedAt().get(), "Value must equals to the intial value");
    one.lastNotifiedAt(
        LocalDateTime.of(1981, 9, 6, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime());
    Assertions.assertEquals(
        LocalDateTime.of(1981, 9, 6, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime(),
        one.getLastNotifiedAt().get(), "Value must equals to the assigned value");
    one.unset("lastNotifiedAt");
    Assertions.assertFalse(one.getLastNotifiedAt().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(0, one.getVersion().get(), "Value must equals to the intial value");
    one.version(2);
    Assertions.assertEquals(2, one.getVersion().get(), "Value must equals to the assigned value");
    one.unset("version");
    Assertions.assertFalse(one.getVersion().isPresent(),
        "After unset, the valeue must be dissapear");
  }
}
